const queries = $('Pull Queries').all();
const responses = $input.all();

return queries.map((q, i) => {
  const r = responses[i].json;
  const judgeUserPrompt = `Score the AI assistant's answer on three dimensions, each 1-5 (1 = poor, 5 = excellent):\n\n- relevance: Does the answer address the question that was asked?\n- accuracy: Are the factual claims plausible given the cited source chunks? Penalize hallucinations.\n- completeness: Does the answer cover what the question asks?\n\nReturn JSON exactly like: {\"relevance\": 5, \"accuracy\": 5, \"completeness\": 4, \"rationale\": \"<one sentence>\"}\n\n---\n\nQUESTION: ${q.json.question}\n\nANSWER: ${r.answer}\n\nCITED CHUNK IDS: ${JSON.stringify(r.retrieved_chunk_ids)}`;

  return {
    json: {
      query_id: q.json.id,
      question: q.json.question,
      answer: r.answer,
      retrieved_chunk_ids: r.retrieved_chunk_ids,
      messages: [
        { role: 'system', content: 'You are an impartial AI evaluation judge for a documentation Q&A system. You return ONLY valid JSON matching the requested schema, no commentary.' },
        { role: 'user', content: judgeUserPrompt }
      ]
    }
  };
});

const prompts = $('Build Judge Prompt').all();
const responses = $input.all();

function clamp(n, lo, hi) {
  const x = Number(n);
  if (!Number.isFinite(x)) return Math.floor((lo + hi) / 2);
  return Math.max(lo, Math.min(hi, Math.round(x)));
}

return prompts.map((p, i) => {
  const content = responses[i].json.choices?.[0]?.message?.content ?? '{}';
  let parsed = {};
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    parsed = {};
  }

  return {
    json: {
      query_id: parseInt(p.json.query_id, 10),
      judge_model: 'gpt-4o',
      relevance: clamp(parsed.relevance, 1, 5),
      accuracy: clamp(parsed.accuracy, 1, 5),
      completeness: clamp(parsed.completeness, 1, 5),
      rationale: parsed.rationale ?? null
    }
  };
});
